using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Animations;
namespace LightingBlocks.Editor {
public static class CreatureMotionRepair {
public static void Apply(string name){const string art="Assets/LightingBlocks/Art/SpectralForest/Twilight";var root=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(art+"/Models/"+name+".fbx"));var body=root.GetComponentsInChildren<Transform>().First(t=>t.name=="Body");string path=AnimationUtility.CalculateTransformPath(body,root.transform);var clips=AssetDatabase.LoadAllAssetsAtPath(art+"/Models/"+name+".fbx").OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__")).ToArray();var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(art+"/"+name+".controller");
foreach(var state in controller.layers[0].stateMachine.states){if(state.state.name!="Hop"&&state.state.name!="Flee")continue;var source=clips.First(c=>c.name.EndsWith("|"+state.state.name));var idle=clips.First(c=>c.name.EndsWith(name=="Bird"?"|GroundIdle":"|Idle"));idle.SampleAnimation(root,0);var origin=body.localPosition;var up=body.parent.InverseTransformVector(root.transform.up);var copy=UnityEngine.Object.Instantiate(source);copy.name=name+"-"+state.state.name;float height=name=="Bird"?.095f:state.state.name=="Flee"?.18f:.12f;
for(int axis=0;axis<3;axis++){var curve=new AnimationCurve();for(int frame=0;frame<=40;frame++){float t=frame/40f;float bounce=Mathf.Max(0,Mathf.Sin(t*Mathf.PI*2));curve.AddKey(t*source.length,origin[axis]+up[axis]*height*bounce);}for(int frame=0;frame<curve.length;frame++)curve.SmoothTangents(frame,0);AnimationUtility.SetEditorCurve(copy,EditorCurveBinding.FloatCurve(path,typeof(Transform),"m_LocalPosition."+"xyz"[axis]),curve);}
var settings=AnimationUtility.GetAnimationClipSettings(copy);settings.loopTime=true;AnimationUtility.SetAnimationClipSettings(copy,settings);string target=art+"/"+copy.name+".anim";var old=AssetDatabase.LoadAssetAtPath<AnimationClip>(target);if(old==null)AssetDatabase.CreateAsset(copy,target);else{EditorUtility.CopySerialized(copy,old);UnityEngine.Object.DestroyImmediate(copy);copy=old;}state.state.motion=copy;EditorUtility.SetDirty(state.state);}
EditorUtility.SetDirty(controller);UnityEngine.Object.DestroyImmediate(root);
}
}}
